#!/bin/bash
GCP_REGION="asia-south1"
DEXTER=`packer build template.json | tail -1`;
image_name=`echo $DEXTER | cut -d ":" -f2- | cut -d ":" -f2`;
gcloud compute instance-templates create cost-optimization-template`date +"%H%d%m%Y"` --description="Instances with Dexter Application installed" --provisioning-model="SPOT" --instance-termination-action="STOP" --machine-type=n1-standard-1 --region=$GCP_REGION --create-disk=boot=true,auto-delete=true,type="pd-standard",size=20GB,disk-resource-policy="costoptimization-boot-disk-snapshot,image="${image_name//[[:blank:]]/}",image-project=XXXX-XXXXXXX-2XXXX6"  --create-disk=auto-delete=true,type="pd-standard",size=10GB,device-name="sdb",disk-resource-policy="costoptimization-extra-disk-snapshot" --labels=environment="dev" --tags="allow-ssh","allow-health-check" --metadata-from-file startup-script="startup-image-template.sh" --network-interface="network=cost-optimization-vpc,subnet=cost-optimization-$GCP_REGION-public-subnet,network-tier=PREMIUM" --metadata=environment="dev" --project=XXXX-XXXXXXX-2XXXX6 --service-account=cost-optimization-sa@XXXX-XXXXXXX-2XXXX6.iam.gserviceaccount.com;
gcloud compute instance-groups managed rolling-action start-update cost-optimization-instance-group --project=XXXX-XXXXXXX-2XXXX6 --version=template=cost-optimization-template`date +"%H%d%m%Y"` --region=$GCP_REGION;
gcloud compute instance-groups managed update cost-optimization-instance-group --project=XXXX-XXXXXXX-2XXXX6 --health-check autohealing-health-check --initial-delay 300 --instance-redistribution-type="PROACTIVE" --region=$GCP_REGION
